using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options backed by a source-generated context
var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> returned: {typedInfo.Type.Name}");

var forecast = new WeatherForecast("Seattle", 18);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo(Type, out JsonTypeInfo?)
//    Returns true/false — no exception if the type isn't registered.
if (options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? info))
    Console.WriteLine($"TryGetTypeInfo(WeatherForecast) => found ({info!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo(WeatherForecast) => not found");

// Try a type the source generator does NOT know about
if (options.TryGetTypeInfo(typeof(DateTime), out _))
    Console.WriteLine("TryGetTypeInfo(DateTime) => found");
else
    Console.WriteLine("TryGetTypeInfo(DateTime) => not found (no metadata registered)");

// Records used in the demo
public record WeatherForecast(string City, int TempC);

// Source-generated context — only WeatherForecast is included
[JsonSerializable(typeof(WeatherForecast))]
partial class AppJsonContext : JsonSerializerContext;

